/// Data models for AppStorys banner campaigns.
///
/// This module provides the data structures needed to parse and render
/// banner campaigns fetched from the AppStorys API via the Dart plugin.

class BannerCampaign {
  final String id;
  final String? image;
  final double? width;
  final double? height;
  final String? link;
  final BannerStyling? styling;
  final String? lottieData;

  BannerCampaign({
    required this.id,
    this.image,
    this.width,
    this.height,
    this.link,
    this.styling,
    this.lottieData,
  });

  factory BannerCampaign.fromJson(Map<String, dynamic> json) {
    return BannerCampaign(
      id: (json['id'] as String?) ?? '',
      image: json['image'] as String?,
      width: (json['width'] as num?)?.toDouble(),
      height: (json['height'] as num?)?.toDouble(),
      link: json['link'] as String?,
      styling: json['styling'] != null
          ? BannerStyling.fromJson(json['styling'] as Map<String, dynamic>)
          : null,
      lottieData: json['lottie_data'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
        'id': id,
        'image': image,
        'width': width,
        'height': height,
        'link': link,
        'styling': styling?.toJson(),
        'lottie_data': lottieData,
      };
}

class BannerStyling {
  final double? topLeftRadius;
  final double? topRightRadius;
  final double? bottomLeftRadius;
  final double? bottomRightRadius;
  final double? marginBottom;
  final double? marginLeft;
  final double? marginRight;
  final CrossButtonStyling? crossButton;

  BannerStyling({
    this.topLeftRadius,
    this.topRightRadius,
    this.bottomLeftRadius,
    this.bottomRightRadius,
    this.marginBottom,
    this.marginLeft,
    this.marginRight,
    this.crossButton,
  });

  factory BannerStyling.fromJson(Map<String, dynamic> json) {
    return BannerStyling(
      topLeftRadius: (json['topLeftRadius'] as num?)?.toDouble(),
      topRightRadius: (json['topRightRadius'] as num?)?.toDouble(),
      bottomLeftRadius: (json['bottomLeftRadius'] as num?)?.toDouble(),
      bottomRightRadius: (json['bottomRightRadius'] as num?)?.toDouble(),
      marginBottom: (json['marginBottom'] as num?)?.toDouble(),
      marginLeft: (json['margin_left'] as num?)?.toDouble(),
      marginRight: (json['margin_right'] as num?)?.toDouble(),
      crossButton: json['crossButton'] != null
          ? CrossButtonStyling.fromJson(json['crossButton'] as Map<String, dynamic>)
          : null,
    );
  }

  Map<String, dynamic> toJson() => {
        'topLeftRadius': topLeftRadius,
        'topRightRadius': topRightRadius,
        'bottomLeftRadius': bottomLeftRadius,
        'bottomRightRadius': bottomRightRadius,
        'marginBottom': marginBottom,
        'margin_left': marginLeft,
        'margin_right': marginRight,
        'crossButton': crossButton?.toJson(),
      };
}

class CrossButtonStyling {
  final bool? enabled;
  final double? size;
  final String? color;

  CrossButtonStyling({
    this.enabled,
    this.size,
    this.color,
  });

  factory CrossButtonStyling.fromJson(Map<String, dynamic> json) {
    return CrossButtonStyling(
      enabled: json['enabled'] as bool?,
      size: (json['size'] as num?)?.toDouble(),
      color: json['color'] as String?,
    );
  }

  Map<String, dynamic> toJson() => {
        'enabled': enabled,
        'size': size,
        'color': color,
      };
}

